"""Render the already consumed cohort result and saved costs; never load labels or models."""
from pathlib import Path
import json,sys,math
P=Path('/workspace/uwb-irm-loso6-20261107')
def read(p):return json.loads(Path(p).read_text())
def main():
    s=read(P/'SUMMARY.json');assert (P/'FINALIZE_ONCE.lock').exists() and s['finalizer_invocations']==1
    audit=read(P/'operator/AUXILIARY_COMPLETE_SIX_AUDIT.json');inf=read(P/'INFERENCE_COST.json');m=read(P/'full_backup/MANIFEST.json');v=read(P/'full_backup/READBACK_VERIFIED.json')
    assert len(s['rows'])==6 and len(inf['rows'])==12 and not inf['held_labels_read'] and v['complete_modelset_verified']
    percent=lambda x:f'{100*x:.6f}%'
    pp=lambda x:f'{100*x:+.6f}'
    lines=['# Frozen IRM100/500 native LOSO6 exploratory result','',f'GAP mean present-class macro recall {percent(s["baseline"]["equal_user_mean_macro_recall"])}; IRM {percent(s["method"]["equal_user_mean_macro_recall"])}; paired mean {pp(s["mean_paired_macro_recall_delta"])} percentage points. Fixed spending gate passed: {s["cohort_spending_gate_passed"]}.','',f'Route: `{s["route"]}`. The one cohort scorer is consumed; no individual held score selected the configuration, epochs, seed or which folds were run. A failed spending gate does not erase any positive per-user effect. No original-contribution or independent-new-user validation claim.','', '|Held|GAP accuracy|IRM accuracy|GAP present macro|IRM present macro|Paired macro pp|n|Missing classes (0-based)|','|---|---:|---:|---:|---:|---:|---:|---|']
    for r in s['rows']:
        b=r['baseline'];a=r['method'];delta=a['present_class_macro_recall']-b['present_class_macro_recall']
        lines.append(f'|{r["held"]}|{percent(b["accuracy"])}|{percent(a["accuracy"])}|{percent(b["present_class_macro_recall"])}|{percent(a["present_class_macro_recall"])}|{pp(delta)}|{a["n"]}|{a["missing_classes"]}|')
    lines+=['','|Aggregate|GAP|IRM|','|---|---:|---:|']
    for k in ['equal_user_mean_macro_recall','equal_user_mean_accuracy','worst_user_macro_recall','pooled_sample_accuracy']:lines.append(f'|{k}|{percent(s["baseline"][k])}|{percent(s["method"][k])}|')
    ties=sum(r['method']['present_class_macro_recall']==r['baseline']['present_class_macro_recall'] for r in s['rows'])
    lines+=['',f'Strict wins: {s["strict_user_wins"]}/6; exact ties: {ties}/6; worst paired macro difference: {pp(s["worst_paired_macro_recall_delta"])} pp. Frozen gate: mean paired gain >=0.5pp, >=4 strict wins, worst paired decline <=2pp (registered tolerance1e-12).','', 'Accuracy is the fraction of all records correct. Present-class macro recall averages only classes with positive true support; missing recalls are null, and predicting an absent class remains an error. Here every present class has100 records, so each user\'s two measures coincide numerically. This does not make the definitions interchangeable. Pooled sample accuracy is separately named and is not the equal-user mean.','', '|Held|Class supports (0..11)|GAP class recalls (null missing)|IRM class recalls (null missing)|','|---|---|---|---|']
    for r in s['rows']:lines.append(f'|{r["held"]}|{json.dumps(r["method"]["class_support"])}|{json.dumps(r["baseline"]["class_recall"])}|{json.dumps(r["method"]["class_recall"])}|')
    lines+=['','## Fixed protocol and reproducibility','', 'Test h1..6; validation h%6+1; the other four subjects train. All role/sample IDs are disjoint within each fold, all6900 source IDs are preserved privately, all six models start from the same untrained native state with fresh optimizer/order/Python/NumPy/Torch RNG. Full GAP617612/all3 signed per-record RMS90x567/B64/64epochs/seed20261029/native global onehot12 BCE/AdamWLookahead are retained. IRM adds the published dummy-scale gradient-product term, warm weight1 before500 completed updates and100 thereafter, and resets the whole native optimizer before update501. Global BCE, native mixed-source batches, pooled BN/dropout and native optimizer reset are declared transfer differences from DomainBed; this is not an author-benchmark reproduction. Native reset is also a difference from the original GAP comparator. A positive cohort therefore needs the preregistered matched globalBCE/reset500/no-IRM six-fold control before penalty attribution or outer8.','', 'All six full64 production and fresh64 replay trajectories, all65 epoch/journal records, every step/native model/optimizer/slow/all RNG/selected outputs were exact. Independent first-step dummy-scale autograd checked all617612 clipped gradients; full same-implementation replay alone cannot exclude common implementation bugs. Model selection was validation-only. All model/trajectory/ID/output private raw-all-member insurance and exact Git release preceded the single score. The saved label-free paired inference pass recomputed all baseline/method logits bitwise and checked parameters/buffers unchanged.','',f'Full archive: {len(m["chunks"])} parts, {m["archive_bytes"]} bytes, {m["tracked_payload_files"]} payloads, SHA256 `{m["archive_sha256"]}`. Verification: {v["archive_members"]} tar members including the member manifest. Raw arrays/runtime binaries remain external via the persistent recovery chain. Extraction/end-to-end interrupted-job resume was not exercised in the intact environment.','', 'Published sources: Arjovsky et al., Invariant Risk Minimization, arXiv1907.02893 (method sections3.1-3.2 reviewed); pinned DomainBed commit b93c22a1cfc3b2428398272c1a116c8de1f4139e. No coefficient, kernel, seed, epoch or fold rescue is permitted after this score. Users7-8 did not select this method; historical exposure to all8 users makes this exploratory, not independent validation.','', '## Costs','', 'Stage costs below are differences of saved cumulative per-fold timers, not sums of cumulative timers. Production includes native loading/validation and the first-step auditor; it is not an isolated pure training kernel measurement. Independent fresh replay is reproduction cost, not extra optimization for the selected production model.','', '|Held|Production stage wall/CPU s|Fresh replay stage wall/CPU s|Output stage wall/CPU s|Selected epoch (validation)|','|---|---:|---:|---:|---:|']
    costs=[]
    for r in audit['rows']:
        h=r['held'];c=s['fold_stage_costs'][str(h)];previous=dict(wall=0.,cpu=0.);parts=[];row=dict(held=h)
        for stage in ['train','replay','output']:
            cur=c[stage];delta={k:cur[k]-previous[k] for k in ['wall','cpu']};assert all(x>=0 for x in delta.values());row[stage]=delta;parts.append(f'{delta["wall"]:.6f}/{delta["cpu"]:.6f}');previous=cur
        costs.append(row);lines.append(f'|{h}|'+ '|'.join(parts)+f'|{r["selected_epoch_validation_only"]}|')
    phase=s['remaining_phase_cost'];lines+=['',f'Whole IRM phase including fold supervision: wall {phase["wall"]:.6f}s / CPU {phase["cpu"]:.6f}s; whole-phase12h wall/CPU caps were not reset between folds. Production updates27776; fresh replay updates27776. Do not add the per-fold stage totals again to this whole-phase total. Native earlier GAP artifacts retain their own historical cost/audit scope (initial/first/selected/output audits, not an asserted full64 fresh replay).','', '|Inference arm (saved label-free fixed pass)|Total measured wall s|Total measured CPU s|Wall ms/record|','|---|---:|---:|---:|']
    inference=[]
    for arm in ['baseline','method']:
        a=[r for r in inf['rows'] if r['arm']==arm];n=sum(r['n'] for r in a);wall=sum(r['wall_seconds'] for r in a);cpu=sum(r['CPU_seconds'] for r in a);inference.append(dict(arm=arm,n=n,wall=wall,CPU=cpu,wall_ms_per_record=wall*1000/n));lines.append(f'|{arm}|{wall:.6f}|{cpu:.6f}|{wall*1000/n:.6f}|')
    lines+=['',f'Full inference worker including loading/checks/warmup: wall {inf["total_worker_wall_seconds"]:.6f}s / CPU {inf["total_worker_CPU_seconds"]:.6f}s; RSS {inf["max_RSS_KiB"]}KiB. Each saved row separately reports warmup. Scorer evaluation wall {s["evaluation_wall_seconds"]:.6f}s.','', 'Insurance/build/network/operator cost receipts are separate artifacts. The full archive build records parent-process CPU only and does not measure child build CPU; that unknown value is not zero. Full network/remote connector CPU is unmeasured. Previous per-fold insurance and this full archive overlap in coverage and must not be called additional model fits. All prior MMD/VREx/Fishr research costs remain separately reported:']
    for label,key in [('MMD','prior_MMD6_cost'),('VREx','prior_VREx6_cost'),('Fishr','prior_Fishr6_cost')]:lines.append(f'- {label}: wall {s[key]["wall"]}s / CPU {s[key]["cpu"]}s (prior MMD held1 is a subcost, never added twice).')
    lines+=['','Historical fixed TimeMIL+Shuffle94.6290% used a different64+100 budget and retained its original failed spending conclusion; it is a historical strong reference, not this matched comparator. Existing old LTR/frozen cross-user penalty and every closed MMD/VREx/Fishr configuration remain unchanged.','']
    out=P/'report_artifacts';out.mkdir(exist_ok=True);(out/'FINAL_REPORT.md').write_text('\n'.join(lines));(out/'COST_BREAKDOWN.json').write_text(json.dumps(dict(stage_differences=costs,inference_measured_totals=inference,whole_phase=phase,full_archive_build_child_CPU_measured=False,full_network_CPU_measured=False),indent=2)+'\n')
    print(json.dumps(dict(report=str(out/'FINAL_REPORT.md'),spending_gate_passed=s['cohort_spending_gate_passed'],route=s['route'],new_scoring_performed=False)))

if __name__=='__main__':main()
